/**
 * HORSE OPTION DECISION COST (read-only; no database, no network). docs/ops/horse-option-cost.md is generated by it.
 *
 * "What does each registered Horse option cost per decision, where it applies, against the same decision with it
 * off?" On 2026-11-26 omahaOopReraiseRangeHoldsVsReraise tripped the live shadow breaker (33-94 ms a re-decision)
 * because nobody had measured it. This runs every registered option through ONE harness so the cost is known before
 * an option is switched, and so the table can be re-run on any tree.
 *
 *   measure  --build <worktree> --states <states dir> --out <run dir>
 *            [--dist <compiled server dir (tsc outDir)>] [--options <switch snapshot json>]
 *            [--only a,b] [--limit <states per option>] [--memory some|off]
 *     Every state of the plan's games goes through HorseLogic.decide twice per option, once with the option's row
 *     `on` and once `off` (mapped by the build's own switch code, the way the worker does it), in alternating
 *     order, same seeds, clocks frozen; each decide is timed with process.hrtime. The option APPLIES at a state when
 *     the decision JSON or its receipts (telemetry fires) differ between the two. One ndjson line per option in
 *     <run dir>/options.ndjson; a re-run skips the options already there (resumable).
 *     Run it from <build>/server with --dist on a tsc build of the same tree (the compiled build the engine runs):
 *     `cd <build>/server && npx tsc --outDir <dist> && node ../scripts/ops/horse-option-cost.mjs measure --dist
 *     <dist> ...`; without --dist it loads the TypeScript source and needs `node --import tsx`.
 *
 *   report   --in <run dir> [--out docs/ops/horse-option-cost.md] [--exclude a,b]
 *     Writes the table: per option, states, applicable states, ON p50/p95/max and the added time (ON minus OFF)
 *     p50/p95/max on the applicable states, and the options over the bar (WORKER-RULES SPEED: p95 > 10 ms, max >
 *     25 ms, anything > 50 ms; the live shadow breaker disables an option after 3 re-decisions over 50 ms in 20, or
 *     one over 150 ms).
 *
 * States: the cross-build replay's seeded league states (scripts/ops/horse-decision-crossbuild-replay.mjs capture),
 * only the games Horses play here: PLO4 / PLO5 cash (table, Lightning), NLH cash (table, Lightning) and NLH
 * tournaments. Harness-generated hands only: no real hole cards.
 *
 * What it does NOT show: an option the seeded states never reach reads "0 applicable" (not "free"); timings are
 * wall time on a shared machine (the report prints the load), so compare rows of one run, not runs of two machines.
 */
import {
  appendFileSync,
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  writeFileSync,
} from 'node:fs';
import { cpus, loadavg } from 'node:os';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import {
  DEFAULT_MEMORY_HANDS,
  FIXED_NOW_MS,
  augmentState,
  optionRowsFromJson,
} from './horse-decision-crossbuild-replay-lib.mjs';
import { decisionOptionsFor, seedMemory } from './horse-decision-crossbuild-replay-engine.mjs';

export const COST_SCHEMA = 'horse-option-cost/v1';
/** The games Horses play (PLO4/PLO5 cash, NLH cash and tournaments); the capture's other groups are skipped. */
export const COST_GROUPS = Object.freeze([
  'plo4_cash_6max',
  'plo4_cash_hu',
  'plo4_cash_345',
  'plo5_cash_6max',
  'plo5_cash_hu',
  'plo5_cash_345',
  'lightning_plo4',
  'lightning_plo5',
  'nlh_cash',
  'lightning_nlh',
  'nlh_tourn',
]);
/** WORKER-RULES SPEED bar, per decision where the option applies. */
export const COST_BAR = Object.freeze({ p95: 10, max: 25, hard: 50 });
/**
 * An over-the-bar option is slow BECAUSE of the option when its own added time (ON minus OFF on the same state) is
 * systematic: a median of at least COST_ADDED_P50_OWN ms, or a p95 of at least COST_ADDED_P95_OWN ms (twice the
 * noise of the paired difference on a loaded machine: options that change nothing measurable show an added p95 of
 * about 8-10 ms and a median near 0 at load 15). Otherwise the decision is as slow with it off (a slow spot or a
 * pause of the shared machine), and it is listed apart.
 */
export const COST_ADDED_P50_OWN = 2;
export const COST_ADDED_P95_OWN = 20;

/** True when an over-the-bar option's own added time explains the breach. */
export function overBarByOption(row, bar = COST_BAR) {
  const add = row.applied?.added;
  void bar;
  return !!add && ((add.p50 ?? 0) >= COST_ADDED_P50_OWN || (add.p95 ?? 0) >= COST_ADDED_P95_OWN);
}
const SEED = 20261122;

export function quantile(values, p) {
  if (!values.length) return null;
  const a = [...values].sort((x, y) => x - y);
  return a[Math.min(a.length - 1, Math.floor(p * a.length))];
}
const r1 = (x) => (x === null || x === undefined ? null : Math.round(x * 10) / 10);

/** p50 / p95 / max of a list of milliseconds (null when empty). */
export function summarize(ms) {
  if (!ms.length) return { n: 0, p50: null, p95: null, max: null };
  return {
    n: ms.length,
    p50: r1(quantile(ms, 0.5)),
    p95: r1(quantile(ms, 0.95)),
    max: r1(Math.max(...ms)),
  };
}

/** The bar breaches of one option row (empty when under the bar or never applicable). */
export function overBar(row, bar = COST_BAR) {
  const on = row.applied?.on;
  if (!on || !on.n) return [];
  const out = [];
  if (on.p95 > bar.p95) out.push(`p95 ${on.p95} > ${bar.p95} ms`);
  if (on.max > bar.max) out.push(`max ${on.max} > ${bar.max} ms`);
  if (row.applied.over50 > 0) out.push(`${row.applied.over50} over ${bar.hard} ms`);
  return out;
}

function parseArgs(argv) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--')) {
      const v = argv[i + 1];
      if (v === undefined || v.startsWith('--')) out[a.slice(2)] = true;
      else {
        out[a.slice(2)] = v;
        i++;
      }
    } else out._.push(a);
  }
  return out;
}

/** One build's engine, from its source (tsx) or from a tsc build of it (--dist). */
async function loadEngine(build, dist) {
  const root = dist ? resolve(dist) : join(resolve(build), 'server', 'src');
  const ext = dist ? '.js' : '.ts';
  const eng = (f) => pathToFileURL(join(root, 'engine', f + ext)).href;
  const [logic, mind, ev, size, time, tel, os, ss] = await Promise.all(
    [
      'HorseLogic',
      'HorseMind',
      'HorseEval',
      'horsePublicBetSize',
      'horsePublicActionTime',
      'BrainTelemetry',
      'HorseOptionSwitch',
      'HorseStyleSwitch',
    ].map((f) => import(eng(f)))
  );
  return {
    HorseLogic: logic.HorseLogic,
    HorseMind: mind.HorseMind,
    readScopeOf: mind.readScopeOf ?? null,
    seedFastRandom: ev.seedFastRandom,
    seedHorseBetSizeRandom: size.seedHorseBetSizeRandom,
    seedHorseTimingRandom: time.seedHorseTimingRandom,
    enableBrainTelemetry: tel.enableBrainTelemetry,
    drainFires: tel.drainFires,
    optionSwitch: os,
    styleSwitch: ss,
    stage: await import(eng('HorseOptionShadowStage')).catch(() => null),
  };
}

export function readCostStates(dir, groups = COST_GROUPS) {
  const out = [];
  for (const f of readdirSync(dir)
    .filter((x) => /^states-.*\.ndjson$/.test(x))
    .sort()) {
    const group = f.slice(7, -7);
    if (!groups.includes(group)) continue;
    const lines = readFileSync(join(dir, f), 'utf8').split('\n').filter(Boolean);
    lines.forEach((line, idx) => out.push({ line, idx, group }));
  }
  return out;
}

/** A decision's own clock readings (latencyMs, elapsedMs, ...) differ run to run; the comparison leaves them out. */
export const untimed = (k, v) => (typeof v === 'number' && /Ms$/.test(k) ? undefined : v);

function decideTimed(B, st, opts, memoryOn) {
  B.HorseMind.reset();
  if (memoryOn) seedMemory(B, st, DEFAULT_MEMORY_HANDS, { seeded: 0, error: 0, unavailable: 0 });
  B.seedFastRandom(SEED);
  B.seedHorseBetSizeRandom(SEED ^ 0x5bd1e995);
  B.seedHorseTimingRandom(SEED ^ 0x9e3779b9);
  B.drainFires();
  const t0 = process.hrtime.bigint();
  let d;
  let error = null;
  try {
    d = B.HorseLogic.decide(st.player, st.gs, st.style, st.mods, {
      ...(st.opts ?? {}),
      ...opts,
      telemetry: true,
      observeMind: false,
      decisionTimeMs: FIXED_NOW_MS,
    });
  } catch (e) {
    error = String(e?.message ?? e).slice(0, 200);
  }
  const ms = Number(process.hrtime.bigint() - t0) / 1e6;
  const fires = B.drainFires()
    .map((f) => `${f.feature}:${f.fires}`)
    .sort()
    .join(',');
  return { ms, sig: error ? `error:${error}` : JSON.stringify(d, untimed) + '|' + fires };
}

/** The ON and OFF decide options of one option, mapped by the build's own switch code. */
export function onOffOpts(B, rows, name) {
  const on = decisionOptionsFor(B, { ...rows, [name]: 'on' }, { expect: { [name]: 'on' } });
  const off = decisionOptionsFor(B, { ...rows, [name]: 'off' }, { expect: { [name]: 'off' } });
  const companions = {};
  const entry = B.stage?.OPTION_SHADOW_STAGE?.[name];
  for (const c of entry?.companions ?? []) if (on.opts[c] !== true) companions[c] = true;
  return {
    on: { ...on.opts, ...companions },
    off: off.opts,
    unmet: [...on.unmet, ...off.unmet],
    companions: Object.keys(companions),
  };
}

async function measure(args) {
  const build = resolve(args.build ?? '.');
  const out = resolve(args.out);
  mkdirSync(out, { recursive: true });
  const B = await loadEngine(build, args.dist);
  B.enableBrainTelemetry();
  const optionsFile = args.options ?? join(build, 'docs', 'horse-option-switch-state.json');
  const { rows, source } = optionRowsFromJson(JSON.parse(readFileSync(optionsFile, 'utf8')));
  const memoryMode = args.memory ?? 'some';
  let states = readCostStates(resolve(args.states));
  if (args.limit) {
    const n = Number(args.limit);
    const step = Math.max(1, Math.floor(states.length / n));
    states = states.filter((_, i) => i % step === 0).slice(0, n);
  }
  const prepared = states.map(({ line, idx, group }) => {
    const st = JSON.parse(line);
    const tags = augmentState(st, st.i0 ?? idx, { memory: memoryMode });
    return { line, idx, group, tags, mem: tags.includes('opponent_memory') };
  });
  const registry = B.optionSwitch.OPTION_SWITCH_REGISTRY;
  const only = args.only ? String(args.only).split(',') : null;
  const done = new Set();
  const file = join(out, 'options.ndjson');
  if (existsSync(file))
    for (const l of readFileSync(file, 'utf8').split('\n').filter(Boolean))
      done.add(JSON.parse(l).name);
  const header = {
    schema: COST_SCHEMA,
    build,
    dist: args.dist ? resolve(args.dist) : null,
    node: process.version,
    cpus: cpus().length,
    cpuModel: cpus()[0]?.model ?? null,
    loadStart: loadavg().map(r1),
    states: prepared.length,
    statesDir: resolve(args.states),
    optionsFile,
    optionsAsOf: source.asOfUtc,
    memory: memoryMode,
    startedUtc: new Date().toISOString(),
  };
  if (!existsSync(join(out, 'header.json')))
    writeFileSync(join(out, 'header.json'), JSON.stringify(header, null, 1));
  const fresh = (p) => {
    const st = JSON.parse(p.line);
    augmentState(st, st.i0 ?? p.idx, { memory: memoryMode });
    return st;
  };
  // a whole-engine warm-up so the first option is not charged the JIT of the shared paths
  const base = decisionOptionsFor(B, rows).opts;
  for (const p of prepared.slice(0, 300)) decideTimed(B, fresh(p), base, p.mem);
  for (const e of registry) {
    if (only && !only.includes(e.name)) continue;
    if (done.has(e.name)) continue;
    const live = rows[e.name] ?? null;
    const row = {
      name: e.name,
      releaseDefault: e.releaseDefault,
      offOnly: e.offOnly ? e.offOnly.status : null,
      productionRow: live,
      liveOn: live === 'on' || live === 'on_shadow' || (live === null && e.releaseDefault === 'on'),
    };
    let oo;
    try {
      oo = onOffOpts(B, rows, e.name);
    } catch (err) {
      row.skipped = `options could not be mapped: ${String(err?.message ?? err).slice(0, 160)}`;
      appendFileSync(file, JSON.stringify(row) + '\n');
      continue;
    }
    if (oo.unmet.length) {
      row.skipped = `the build does not apply on/off: ${oo.unmet.join('; ').slice(0, 200)}`;
      appendFileSync(file, JSON.stringify(row) + '\n');
      continue;
    }
    row.companions = oo.companions;
    // the option's own warm-up: its paths compiled before timing
    for (const p of prepared.slice(0, 120)) decideTimed(B, fresh(p), oo.on, p.mem);
    const all = { on: [], off: [] };
    const app = { on: [], off: [], add: [] };
    const byGroup = {};
    let errors = 0;
    prepared.forEach((p, i) => {
      const onFirst = i % 2 === 0;
      const a = onFirst ? decideTimed(B, fresh(p), oo.on, p.mem) : null;
      const b = decideTimed(B, fresh(p), oo.off, p.mem);
      const c = onFirst ? a : decideTimed(B, fresh(p), oo.on, p.mem);
      if (c.sig.startsWith('error:') || b.sig.startsWith('error:')) errors++;
      all.on.push(c.ms);
      all.off.push(b.ms);
      if (c.sig !== b.sig) {
        app.on.push(c.ms);
        app.off.push(b.ms);
        app.add.push(c.ms - b.ms);
        const g = (byGroup[p.group] ??= []);
        g.push(c.ms);
      }
    });
    row.states = prepared.length;
    row.errors = errors;
    row.all = { on: summarize(all.on), off: summarize(all.off) };
    row.applied = {
      n: app.on.length,
      on: summarize(app.on),
      off: summarize(app.off),
      added: summarize(app.add),
      over50: app.on.filter((x) => x > COST_BAR.hard).length,
      groups: Object.fromEntries(Object.entries(byGroup).map(([g, v]) => [g, summarize(v)])),
    };
    row.load = loadavg().map(r1);
    appendFileSync(file, JSON.stringify(row) + '\n');
    console.log(
      `${e.name}: applies ${row.applied.n}/${row.states}, on p95 ${row.applied.on.p95 ?? '-'} max ${row.applied.on.max ?? '-'} ms`
    );
  }
  writeFileSync(
    join(out, 'footer.json'),
    JSON.stringify({ endedUtc: new Date().toISOString(), loadEnd: loadavg().map(r1) }, null, 1)
  );
}

const cell = (x) => (x === null || x === undefined ? '-' : String(x));

/** The markdown report of a run directory (pure: rows in, text out). */
export function formatCostReport(header, footer, rows, bar = COST_BAR) {
  const L = [];
  L.push('# Horse Option Decision Cost');
  L.push('');
  L.push(
    'GENERATED by `scripts/ops/horse-option-cost.mjs report`; do not edit by hand. Re-run: see "How To Re-Run" below.'
  );
  L.push('');
  L.push(
    "Per registered option: every seeded state of the games Horses play decided with the option `on` and `off` (rows mapped by the build's own switch code, alternating order, same seeds). The option **applies** at a state when the decision or its receipts differ. Times are the engine's own `HorseLogic.decide` per decision, in ms, on the applicable states: **ON** is the decision with the option on, **added** is ON minus OFF on the same state."
  );
  L.push('');
  L.push(
    `Run: ${header.dist ? 'compiled build (tsc)' : 'source (tsx)'}, ${header.states} states, memory ${header.memory}, node ${header.node}, ${header.cpuModel ?? ''} x${header.cpus}, load ${header.loadStart?.join('/')} at start, ${footer?.loadEnd?.join('/') ?? '?'} at end; switch snapshot as of ${header.optionsAsOf}; started ${header.startedUtc}.`
  );
  L.push('');
  if (header.excluded)
    L.push(
      `${header.excluded} option(s) left out of this table on the command line (owner rule: not to be listed).`,
      ''
    );
  L.push(
    `Bar (WORKER-RULES SPEED, where the option applies): p95 <= ${bar.p95} ms, max <= ${bar.max} ms, nothing over ${bar.hard} ms. The live shadow breaker switches an option off after 3 re-decisions over 50 ms in 20, or one over 150 ms.`
  );
  L.push('');
  const measured = rows.filter((r) => !r.skipped);
  const over = measured
    .map((r) => ({ r, why: overBar(r, bar) }))
    .filter((x) => x.why.length)
    .sort((a, b) => (b.r.applied.on.max ?? 0) - (a.r.applied.on.max ?? 0));
  const own = over.filter((x) => overBarByOption(x.r, bar));
  const shared = over.filter((x) => !overBarByOption(x.r, bar));
  const overTable = (title, note, list) => {
    L.push(`## ${title} (${list.length})`);
    L.push('');
    L.push(note);
    L.push('');
    if (!list.length) {
      L.push('None.');
      L.push('');
      return;
    }
    L.push(
      '| option | live | applies | ON p50 | ON p95 | ON max | added p50 | added p95 | added max | OFF max (same states) | breach |'
    );
    L.push('|---|---|---|---|---|---|---|---|---|---|---|');
    for (const { r, why } of list)
      L.push(
        `| ${r.name} | ${r.liveOn ? 'on' : 'off'} | ${r.applied.n} | ${cell(r.applied.on.p50)} | ${cell(r.applied.on.p95)} | ${cell(r.applied.on.max)} | ${cell(r.applied.added.p50)} | ${cell(r.applied.added.p95)} | ${cell(r.applied.added.max)} | ${cell(r.applied.off.max)} | ${why.join('; ')} |`
      );
    L.push('');
  };
  overTable(
    'Over The Bar Because Of The Option',
    `The option's own added time (ON minus OFF on the same state) is systematic: a median of at least ${COST_ADDED_P50_OWN} ms, or a p95 of at least ${COST_ADDED_P95_OWN} ms. These are the options to fix, or to keep out of shadow, before they are switched.`,
    own
  );
  overTable(
    'Over The Bar On The Decision Alone',
    `The ON decision breaches the bar, but the option's added time has a median under ${COST_ADDED_P50_OWN} ms and a p95 under ${COST_ADDED_P95_OWN} ms: the same decisions are slow with it off too (a slow spot, or a pause of the shared machine at load ${header.loadStart?.[0] ?? '?'}). Not the option's own cost; re-measure on a quiet machine before acting on one.`,
    shared
  );
  const table = (title, list) => {
    L.push(`## ${title} (${list.length})`);
    L.push('');
    L.push(
      '| option | default | prod row | applies | ON p50 | ON p95 | ON max | added p50 | added p95 | added max | all-states ON p95 / OFF p95 |'
    );
    L.push('|---|---|---|---|---|---|---|---|---|---|---|');
    for (const r of list)
      L.push(
        `| ${r.name} | ${r.releaseDefault} | ${r.productionRow ?? '-'} | ${r.applied.n}/${r.states} | ${cell(r.applied.on.p50)} | ${cell(r.applied.on.p95)} | ${cell(r.applied.on.max)} | ${cell(r.applied.added.p50)} | ${cell(r.applied.added.p95)} | ${cell(r.applied.added.max)} | ${cell(r.all.on.p95)} / ${cell(r.all.off.p95)} |`
      );
    L.push('');
  };
  table(
    'Not Live-On (switchable, off in production)',
    measured.filter((r) => !r.liveOn)
  );
  table(
    'Live-On (baseline)',
    measured.filter((r) => r.liveOn)
  );
  const skipped = rows.filter((r) => r.skipped);
  L.push(`## Not Measured (${skipped.length})`);
  L.push('');
  L.push(
    'An off-only option cannot be switched on, so it cannot change a live decision; anything else here could not be mapped by the build.'
  );
  L.push('');
  for (const r of skipped)
    L.push(`- ${r.name}: ${r.offOnly ? `off-only (${r.offOnly})` : r.skipped}`);
  L.push('');
  L.push('## How To Re-Run');
  L.push('');
  L.push('```');
  L.push('W=<worktree>; S=<scratch on the external SSD>');
  L.push(
    'node $W/scripts/ops/horse-decision-crossbuild-replay.mjs capture --build $W --out $S/states --set quick --jobs 2 \\'
  );
  L.push(`  --groups ${COST_GROUPS.join(',')}`);
  L.push(
    'cd $W/server && npx tsc --outDir $S/dist --declaration false --declarationMap false --sourceMap false'
  );
  L.push(
    `node ../scripts/ops/horse-option-cost.mjs measure --build $W --dist $S/dist --states $S/states --out $S/cost --limit ${header.states}`
  );
  L.push(
    `node ../scripts/ops/horse-option-cost.mjs report --in $S/cost --out ../docs/ops/horse-option-cost.md${header.excluded ? ' --exclude <the option(s) left out>' : ''}`
  );
  L.push('```');
  L.push('');
  L.push(
    'What it does not show: an option the seeded states never reach reads 0 applicable, which is not "free"; an option that applies only with a real opponent record or a rare spot needs its own harness (its cost law). Wall time on a shared machine: compare rows of one run.'
  );
  L.push('');
  return L.join('\n');
}

function report(args) {
  const dir = resolve(args.in);
  const header = JSON.parse(readFileSync(join(dir, 'header.json'), 'utf8'));
  const footer = existsSync(join(dir, 'footer.json'))
    ? JSON.parse(readFileSync(join(dir, 'footer.json'), 'utf8'))
    : null;
  const exclude = args.exclude ? String(args.exclude).split(',') : [];
  const rows = readFileSync(join(dir, 'options.ndjson'), 'utf8')
    .split('\n')
    .filter(Boolean)
    .map((l) => JSON.parse(l))
    .filter((r) => !exclude.includes(r.name));
  const text = formatCostReport({ ...header, excluded: exclude.length }, footer, rows);
  if (args.out) writeFileSync(resolve(args.out), text);
  else process.stdout.write(text);
  const over = rows.filter((r) => !r.skipped && overBar(r).length).map((r) => r.name);
  console.error(`options ${rows.length}, over the bar ${over.length}: ${over.join(', ')}`);
}

const isMain = process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url;
if (isMain) {
  const args = parseArgs(process.argv.slice(2));
  const cmd = args._[0];
  (cmd === 'measure'
    ? measure(args)
    : cmd === 'report'
      ? Promise.resolve(report(args))
      : null
  )?.catch((e) => {
    console.error(String(e?.stack ?? e));
    process.exit(2);
  }) ??
    (console.error(
      readFileSync(new URL(import.meta.url), 'utf8')
        .split('\n')
        .slice(1, 31)
        .join('\n')
    ),
    process.exit(2));
}
